SELECT YEAR(sessions.started_at) AS started_year, DATE_TRUNC('MONTH', sessions.started_at) AS started_month, SORT_ARRAY(COLLECT_SET(web_events.event_type)) AS event_type_list FROM web_events INNER JOIN sessions ON web_events.session_id = sessions.id LEFT JOIN customers ON sessions.customer_id = customers.id GROUP BY YEAR(sessions.started_at), DATE_TRUNC('MONTH', sessions.started_at) ORDER BY started_year
